UPDATE `kkirikkiri`.`articles`
SET view = view + 1
WHERE id = #{id}

mapper.select:
SELECT `t1`.`id` AS `id`, `t1`.`board_id` AS `boardId`, `t1`.`title` AS `title`, `t1`.`menu` AS `menu`, `t1`.`menu_name` AS `menuName`, `t1`.`min_order_price` AS `minOrderPrice`, `t1`.`order_price` AS `orderPrice`, `t1`.`delivery_price` AS `deliveryPrice`, `t1`.`order_time` AS `orderTime`, `t1`.`restaurant` AS `restaurant`, `t1`.`pickup_time` AS `pickupTime`, `t1`.`address_postal` AS `addressPostal`, `t1`.`address_primary` AS `addressPrimary`, `t1`.`address_secondary` AS `addressSecondary`, `t1`.`content` AS `content`, `t1`.`nickname` AS `nickname`, `t1`.`created_at` AS `createdAt`, `t1`.`updated_at` AS `updatedAt`, `t1`.`view` AS `view` FROM `kkirikkiri`.`articles` AS `t1` WHERE `t1`.`board_id` = #{boardSearch.id}
AND (`t1`.`title` LIKE CONCAT('%', #{boardSearch.keyword}, '%') OR `t1`.`content` LIKE CONCAT('%', #{boardSearch.keyword}, '%') OR `t1`.`nickname` LIKE CONCAT('%', #{boardSearch.keyword}, '%'))
AND `t1`.`title` LIKE CONCAT('%', #{boardSearch.keyword}, '%')
AND `t1`.`nickname` = #{boardSearch.keyword}
ORDER BY `t1`.`id` DESC LIMIT #{boardPage.rowCount} OFFSET #{boardPage.dbOffset}

SELECT COUNT(0)
FROM `kkirikkiri`.`articles` AS `t1`
WHERE `t1`.`board_id` = #{boardSearch.id}

    AND (
    `t1`.`title` LIKE CONCAT('%', #{boardSearch.keyword}, '%')
    OR `t1`.`content` LIKE CONCAT('%', #{boardSearch.keyword}, '%')
    OR `t1`.`nickname` LIKE CONCAT(`%`, #{boardSearch.keyword}, `%`)
    )



    AND `t1`.`title` LIKE CONCAT('%', #{boardSearch.keyword}, '%')



    AND `t1`.`nickname` = #{boardSearch.keyword}
